#!/usr/bin/env node
// Copies the EA input table of docs/js/params.js (PARAMS, GROUPS) into the generated block of
// supabase/functions/chat/index.ts, between
//   // BEGIN params (generated by tools/sync_chat_params.mjs)
//   // END params
// The Edge Function is one pasted file, so it cannot import the website's module; this keeps the assistant's settings
// reference and the proposal checks (remote allow-list, bounds) equal to the website's.
//
//   node tools/sync_chat_params.mjs           rewrite the block
//   node tools/sync_chat_params.mjs --check   exit 1 when the block is out of date (used by the chat tests)

import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const PARAMS_JS = path.join(ROOT, 'docs', 'js', 'params.js');
const TARGET = path.join(ROOT, 'supabase', 'functions', 'chat', 'index.ts');
export const BEGIN = '// BEGIN params (generated by tools/sync_chat_params.mjs)';
export const END = '// END params';

// Field order of every generated entry (only the fields the entry has; flags only when true, `remote` always).
const FIELDS = ['key', 'group', 'type', 'def', 'min', 'max', 'step', 'remote', 'lots', 'capPct', 'rmin', 'rmax', 'rminEx', 'minutes', 'advanced', 'command', 'label', 'help'];
const FLAGS = new Set(['lots', 'capPct', 'minutes', 'advanced', 'command']);

export async function buildBlock(eol = '\n') {
  const { PARAMS, GROUPS, COMMANDS = [], COMMAND_WINDOW_S = 48 * 3600 } = await import(pathToFileURL(PARAMS_JS).href);
  if (!Array.isArray(PARAMS) || !Array.isArray(GROUPS)) throw new Error('docs/js/params.js must export PARAMS and GROUPS');
  const entry = (p) => {
    const o = {};
    for (const f of FIELDS) {
      if (!(f in p) || p[f] === undefined || p[f] === null) continue;
      if (FLAGS.has(f) && p[f] !== true) continue;
      o[f] = f === 'remote' ? p[f] === true : p[f];
    }
    if (!('remote' in o)) o.remote = false;
    return JSON.stringify(o);
  };
  const group = (g) => { const o = { id: g.id, title: g.title, en: g.en }; if (g.hint) o.hint = g.hint; return JSON.stringify(o); };
  const lines = [
    BEGIN,
    `// ${PARAMS.length} EA inputs and ${COMMANDS.length} remote command(s) from docs/js/params.js (do not edit here: edit params.js and run the script)`,
    'const PARAM_GROUPS: ParamGroup[] = [',
    ...GROUPS.map((g) => `  ${group(g)},`),
    '];',
    'const PARAMS: ParamDef[] = [',
    ...PARAMS.map((p) => `  ${entry(p)},`),
    '];',
    '// one-shot remote commands (SPEC 11): not EA inputs, carried in desired.params next to the remote keys',
    'const COMMANDS: CommandDef[] = [',
    ...COMMANDS.map((c) => `  ${entry(c)},`),
    '];',
    `const COMMAND_WINDOW_S = ${Number(COMMAND_WINDOW_S)};`,
    END,
  ];
  return lines.join(eol);
}

export async function sync({ check = false } = {}) {
  const src = readFileSync(TARGET, 'utf8');
  const eol = src.includes('\r\n') ? '\r\n' : '\n';
  const a = src.indexOf(BEGIN), b = src.indexOf(END, a + BEGIN.length);
  if (a < 0 || b < 0) throw new Error(`markers not found in ${path.relative(ROOT, TARGET)}`);
  const next = src.slice(0, a) + (await buildBlock(eol)) + src.slice(b + END.length);
  if (next === src) return { changed: false };
  if (!check) writeFileSync(TARGET, next, 'utf8');
  return { changed: true };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const check = process.argv.includes('--check');
  try {
    const { changed } = await sync({ check });
    if (check && changed) {
      console.error('supabase/functions/chat/index.ts: the params block is out of date. Run: node tools/sync_chat_params.mjs');
      process.exit(1);
    }
    console.log(check ? 'chat params block is up to date' : changed ? 'chat params block updated' : 'chat params block already up to date');
  } catch (e) {
    console.error(String(e && e.message ? e.message : e));
    process.exit(2);
  }
}
